<script setup>
import { computed, ref } from 'vue';
import { Head, usePage } from '@inertiajs/vue3';
import axios from 'axios';
import AppLayout from '@/Layouts/AppLayout.vue';
import ModuleSubTopNav from '@/Navigation/ModuleSubTopNav.vue';

const props = defineProps({ workspace: Object });
const data = ref(props.workspace);
const permissions = computed(() => data.value.permissions);
const from = ref(data.value.summary.from), to = ref(data.value.summary.to);
const page = ref(1), search = ref(''), busy = ref(false), message = ref(''), failed = ref(false);
const tab = ref(new URLSearchParams(usePage().url.split('?')[1] || '').get('view') || 'dashboard');
const tabs = { dashboard: 'Dashboard', accounts: 'Chart of Accounts', journals: 'Journals', ledger: 'General Ledger', trial: 'Trial Balance', reports: 'Financial Reports', audit: 'Audit Trail', tally: 'TallyPrime' };
const account = ref(null), journal = ref(null), confirmation = ref(null), reason = ref(''), reversalDate = ref(to.value);
const ledgerId = ref(''), ledger = ref(null), report = ref('profit'), audit = ref(null), accountPage = ref(1);
const company = ref(data.value.tally?.settings?.tally_company || ''), enabled = ref(Boolean(data.value.tally?.settings?.tally_enabled));
const period = ref(to.value.slice(0, 7)), periodClosed = ref(true), periodReason = ref('');
const connection = ref(null);
const key = () => crypto.randomUUID?.() || Array.from(crypto.getRandomValues(new Uint8Array(16)), x => x.toString(16).padStart(2,'0')).join('');
const url = (name, extra = {}) => route('accounting.' + name, { from: from.value, to: to.value, search: search.value, page: page.value, ...extra, plant_id: data.value.plant_id });
const money = value => {
    const text = String(value || '0');
    const match = /^(-?)(\d+)(?:\.(\d{1,4}))?$/.exec(text);
    if (!match) return text;
    const fraction = (match[3] || '').padEnd(2,'0').replace(/0{1,2}$/, '').padEnd(2,'0');
    return match[1] + new Intl.NumberFormat('en-IN').format(BigInt(match[2])) + '.' + fraction;
};
const filteredAccounts = computed(() => data.value.accounts.filter(a => `${a.code} ${a.title} ${a.type}`.toLowerCase().includes(search.value.toLowerCase())));
const shownAccounts = computed(() => filteredAccounts.value.slice((accountPage.value - 1) * 50, accountPage.value * 50));
const names = computed(() => Object.fromEntries(data.value.accounts.map(a => [a.id, a.title])));
const editableJournal = computed(() => journal.value && journal.value.is_status === 'DRAFT');
async function refresh() { data.value = (await axios.get(url('data'))).data; }
async function selectTab(value) {
    const reload = page.value !== 1;
    tab.value = value; page.value = 1;
    if (reload) await run(async () => {});
}
async function run(fn, success = '') {
    if (busy.value) return;
    busy.value = true; message.value = ''; failed.value = false;
    try { await fn(); await refresh(); message.value = success; }
    catch (e) { failed.value = true; message.value = Object.values(e.response?.data?.errors || {}).flat().join(' ') || e.response?.data?.message || e.message; }
    finally { busy.value = false; }
}
function editAccount(a = null) {
    account.value = a ? { ...a, ledger_id: a.id, id: a.classification_id, active: Boolean(a.active ?? a.status), parent_id: a.parent_id || '', tax_class: a.tax_class || '', control: a.control || '' } : { id: null, code: '', title: '', type: 'asset', account_type_id: '', parent_id: '', tax_class: '', control: '', active: true };
}
async function saveAccount() {
    await run(async () => {
        const a = account.value;
        const payload = { ...a, parent_id: a.parent_id || null, tax_class: a.tax_class || null, control: a.control || null };
        await axios[a.id ? 'put' : 'post'](url(a.id ? 'accounts.update' : 'accounts.store', a.id ? { id: a.id } : {}), payload);
        account.value = null;
    }, 'Account saved.');
}
function newJournal() { journal.value = { request_key: key(), date: to.value, reference: '', narration: '', is_status: 'DRAFT', lines: [{ account_id: '', debit: '0', credit: '0', narration: '' }, { account_id: '', debit: '0', credit: '0', narration: '' }] }; }
async function openJournal(id) {
    await run(async () => {
        const j = (await axios.get(url('journals.show', { id }))).data;
        journal.value = { ...j, date: j.voucher_date.slice(0, 10), reference: j.ref_name || '', request_key: key(), lines: j.lines.map(l => ({ account_id: l.account_id, debit: String(l.debit_amount), credit: String(l.credit_amount), narration: l.line_narration || '' })) };
    });
}
async function saveJournal() {
    await run(async () => {
        const j = journal.value;
        await axios[j.id ? 'put' : 'post'](url(j.id ? 'journals.update' : 'journals.store', j.id ? { id: j.id } : {}), j);
        journal.value = null;
    }, 'Balanced draft saved. Posting requires separate permission.');
}
async function loadLedger() {
    if (!ledgerId.value) return;
    await run(async () => { ledger.value = (await axios.get(url('ledger', { account_id: ledgerId.value }))).data; });
}
function confirm(action, record) { confirmation.value = { action, record, request_key: key() }; reason.value = ''; reversalDate.value = to.value; }
async function execute() {
    await run(async () => {
        const c = confirmation.value;
        if (c.action === 'delete') await axios.delete(url('journals.delete', { id: c.record.id }));
        else if (c.action === 'reverse') await axios.post(url('journals.reverse', { id: c.record.id }), { date: reversalDate.value, reason: reason.value, request_key: c.request_key });
        else if (c.action === 'resolve') await axios.post(url('tally.resolve', { id: c.record.id }), { action: c.resolution, reason: reason.value });
        else await axios.post(url(c.action, { id: c.record.id }));
        confirmation.value = null; journal.value = null;
    }, 'Operation recorded. Review the resulting status.');
}
async function paginate(delta) { page.value += delta; if (tab.value === 'ledger') await loadLedger(); else await run(async () => {}); }
const exportUrl = type => url('export', { report: type, ...(ledgerId.value ? { account_id: ledgerId.value } : {}) });
</script>

<template>
    <Head title="Accounting & GST" />
    <AppLayout title="Accounting & GST"><ModuleSubTopNav />
        <main class="mx-auto max-w-screen-2xl space-y-4 p-4 md:p-6">
            <header class="flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-2xl font-bold">Accounting & GST</h1><p class="text-sm text-slate-500">Plant {{ data.plant_id }} · INR · Posted portal books</p></div><a :href="route('gst-compliance.index')" class="acc-button">GST Reconciliation & GSTR-3B Review</a></header>
            <form class="flex flex-wrap items-end gap-3 rounded border bg-white p-4" @submit.prevent="page = 1; run(async () => { ledger = null; })"><label>From<input v-model="from" type="date" required /></label><label>To<input v-model="to" type="date" required :min="from" /></label><label>Search / reference<input v-model="search" maxlength="100" @input="accountPage = 1" /></label><button :disabled="busy" class="acc-button">{{ busy ? 'Loading…' : 'Apply filters' }}</button></form>
            <p v-if="message" role="status" :class="failed ? 'bg-red-50 text-red-800' : 'bg-emerald-50 text-emerald-800'" class="rounded p-3">{{ message }}</p>
            <nav class="flex flex-wrap gap-2" aria-label="Accounting sections"><button v-for="(label, value) in tabs" v-show="value !== 'tally' || permissions.TALLY" :key="value" class="acc-button" :class="tab === value ? 'bg-indigo-100' : ''" :disabled="busy" @click="selectTab(value)">{{ label }}</button></nav>
            <div v-if="data.summary.warnings.length" class="rounded border border-amber-300 bg-amber-50 p-3"><p class="font-semibold">Review required</p><p v-for="warning in data.summary.warnings" :key="warning" class="text-sm">{{ warning }}</p></div>
            <section v-if="tab === 'dashboard'" class="space-y-4">
                <div class="grid grid-cols-2 gap-3 lg:grid-cols-4"><div v-for="(value, label) in data.summary.profit_loss" :key="label" class="acc-card"><p class="capitalize text-slate-500">{{ label }}</p><strong class="text-xl">₹ {{ money(value) }}</strong></div><div class="acc-card"><p>Trial balance difference</p><strong>₹ {{ money(data.summary.totals.closing) }}</strong></div></div>
                <div class="grid gap-3 md:grid-cols-2"><div class="acc-card"><h2 class="font-semibold">Control account balances</h2><p v-for="(v,k) in data.summary.controls" :key="k">{{ k }}: {{ v === null ? 'Not classified' : '₹ ' + money(v) }}</p><p class="text-sm text-slate-500">Based on explicitly assigned control classifications; classify the relevant ledgers to include them.</p></div><div class="acc-card"><h2 class="font-semibold">GST ledger movements</h2><p v-for="(v,k) in data.summary.gst" :key="k">{{ k }}: ₹ {{ money(v) }}</p><p v-if="!Object.keys(data.summary.gst).length">No tax-classified ledger movements.</p><p class="text-sm text-slate-500">Accounting movements require separate GST eligibility review.</p></div></div>
                <div class="acc-card"><h2 class="font-semibold">Bank reconciliation</h2><p v-if="data.summary.reconciliation">{{ data.summary.reconciliation.matched }} of {{ data.summary.reconciliation.total }} statement rows reconciled in this date range.</p><p v-else>Bank statement data is unavailable.</p></div>
                <div class="acc-card"><h2 class="font-semibold">Recent journals</h2><p v-for="j in data.journals.data.slice(0,10)" :key="j.id"><button class="text-indigo-700" @click="openJournal(j.id)">{{ j.voucher_number }}</button> · {{ j.voucher_date }} · {{ j.reversed_by ? 'REVERSED' : j.is_status }} · ₹ {{ money(j.total_debit) }}</p><p v-if="!data.journals.data.length">No journals for this date range.</p></div>
            </section>
            <section v-if="tab === 'accounts'" class="acc-card space-y-3"><div class="flex justify-between"><h2 class="font-semibold">Chart of Accounts</h2><button v-if="permissions.CREATE" class="acc-button" @click="editAccount()">New account</button></div><p class="text-sm">Existing ledgers share the portal's books. Classify them before using them for new workspace journals. Opening balances are balanced journals against your verified equity/control accounts.</p><div class="overflow-x-auto"><table><thead><tr><th>Code</th><th>Name</th><th>Type</th><th>Tax / control</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="a in shownAccounts" :key="a.id"><td>{{ a.code }}</td><td>{{ a.title }}</td><td>{{ a.type }}</td><td>{{ a.tax_class || a.control || '—' }}</td><td>{{ a.status ? 'Active' : 'Inactive' }}</td><td><button v-if="a.classification_id ? permissions.UPDATE : permissions.CREATE" class="acc-button" @click="editAccount(a)">{{ a.classification_id ? 'Edit' : 'Classify' }}</button></td></tr><tr v-if="!shownAccounts.length"><td colspan="6">No accounts match.</td></tr></tbody></table></div><div class="flex items-center gap-3"><button class="acc-button" :disabled="accountPage === 1" @click="accountPage--">Previous</button><span>Page {{ accountPage }} · {{ filteredAccounts.length }} accounts</span><button class="acc-button" :disabled="accountPage * 50 >= filteredAccounts.length" @click="accountPage++">Next</button></div></section>
            <section v-if="tab === 'journals'" class="acc-card space-y-3"><div class="flex justify-between"><h2 class="font-semibold">Journal register</h2><div class="flex gap-2"><a v-if="permissions.EXPORT" class="acc-button" :href="exportUrl('journals')">Export CSV</a><button v-if="permissions.CREATE" class="acc-button" @click="newJournal">New journal / opening</button></div></div><div class="overflow-x-auto"><table><thead><tr><th>Voucher</th><th>Date / reference</th><th>Description</th><th>Debit</th><th>Credit</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="j in data.journals.data" :key="j.id"><td><button class="text-indigo-700" @click="openJournal(j.id)">{{ j.voucher_number }}</button></td><td>{{ j.voucher_date }}<small class="block">{{ j.ref_name }}</small></td><td>{{ j.narration }}</td><td>{{ money(j.total_debit) }}</td><td>{{ money(j.total_credit) }}</td><td>{{ j.reversed_by ? 'REVERSED' : j.is_status }}<small v-if="j.reversal_of_id" class="block">Reverses #{{ j.reversal_of_id }}</small></td><td class="space-x-2"><template v-if="j.ref_module === 'accounting' && j.is_status === 'DRAFT'"><button v-if="permissions.POST" class="acc-button" @click="confirm('journals.post',j)">Post</button><button v-if="permissions.UPDATE" class="acc-button" @click="confirm('delete',j)">Delete draft</button></template><template v-if="j.is_status === 'POSTED'"><button v-if="permissions.REVERSE && !j.reversed_by" class="acc-button" @click="confirm('reverse',j)">Reverse</button><button v-if="permissions.TALLY && j.ref_module !== 'tally_import'" class="acc-button" @click="confirm('tally.enqueue',j)">Queue Tally</button></template></td></tr><tr v-if="!data.journals.data.length"><td colspan="7">No journals for this date range.</td></tr></tbody></table></div><div class="flex items-center gap-3"><button class="acc-button" :disabled="busy || page === 1" @click="paginate(-1)">Previous</button><span>Page {{ page }} · {{ data.journals.total }} entries</span><button class="acc-button" :disabled="busy || !data.journals.next_page_url" @click="paginate(1)">Next</button></div></section>
            <section v-if="tab === 'trial' || tab === 'reports'" class="acc-card space-y-3"><h2 class="font-semibold">{{ tab === 'trial' ? 'Trial balance & account activity' : 'Financial reports' }}</h2><div v-if="tab === 'reports'" class="flex gap-3"><select v-model="report"><option value="profit">Profit and loss</option><option value="balance">Balance sheet</option></select><a v-if="permissions.EXPORT" :href="exportUrl(report)" class="acc-button">Export CSV</a></div><a v-else-if="permissions.EXPORT" :href="exportUrl('trial')" class="acc-button inline-block">Export CSV</a><div v-if="tab === 'reports'" class="grid grid-cols-2 gap-3 md:grid-cols-4"><p v-for="(v,k) in report === 'profit' ? data.summary.profit_loss : data.summary.balance_sheet" :key="k" class="rounded bg-slate-50 p-3"><span class="capitalize">{{ k.replaceAll('_',' ') }}</span><strong class="block">₹ {{ money(v) }}</strong></p></div><p class="text-sm">Positive balances are debit balances. Balance sheet includes cumulative income and expense balances as retained result through the end date. Profit and loss uses activity within the selected range.</p><div class="overflow-x-auto"><table><thead><tr><th>Code</th><th>Account</th><th>Type</th><th>Opening</th><th>Debits</th><th>Credits</th><th>Closing</th></tr></thead><tbody><tr v-for="a in data.summary.accounts.filter(a => tab === 'trial' || report === 'balance' || ['income','expense'].includes(a.type))" :key="a.account_id"><td>{{ a.code }}</td><td>{{ a.title }}</td><td>{{ a.type }}</td><td>{{ money(a.opening) }}</td><td>{{ money(a.debit) }}</td><td>{{ money(a.credit) }}</td><td>{{ money(a.closing) }}</td></tr></tbody><tfoot v-if="tab === 'trial'"><tr><th colspan="3">Totals</th><th>{{ money(data.summary.totals.opening) }}</th><th>{{ money(data.summary.totals.debit) }}</th><th>{{ money(data.summary.totals.credit) }}</th><th>{{ money(data.summary.totals.closing) }}</th></tr></tfoot></table></div><p v-if="tab === 'trial'">Closing debit balances: ₹ {{ money(data.summary.totals.trial_debit) }} · Closing credit balances: ₹ {{ money(data.summary.totals.trial_credit) }}</p></section>
            <section v-if="tab === 'ledger'" class="acc-card space-y-3"><h2 class="font-semibold">General ledger</h2><form class="flex flex-wrap gap-3" @submit.prevent="page = 1; loadLedger()"><select v-model="ledgerId" required><option value="" disabled>Select account</option><option v-for="a in data.accounts" :key="a.id" :value="a.id">{{ a.code }} · {{ a.title }}</option></select><button class="acc-button" :disabled="busy">Load ledger</button><a v-if="permissions.EXPORT && ledgerId" :href="exportUrl('ledger')" class="acc-button">Export CSV</a></form><template v-if="ledger"><p>Opening ₹ {{ money(ledger.opening) }} · Closing ₹ {{ money(ledger.closing) }}. Running balances include all account activity even when a reference filter hides rows.</p><div class="overflow-x-auto"><table><thead><tr><th>Date</th><th>Voucher / reference</th><th>Description</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody><tr v-for="l in ledger.rows" :key="l.id"><td>{{ l.voucher_date }}</td><td>{{ l.voucher_number }} · {{ l.ref_name }}</td><td>{{ l.narration }}</td><td>{{ money(l.debit_amount) }}</td><td>{{ money(l.credit_amount) }}</td><td>{{ money(l.running_balance) }}</td></tr><tr v-if="!ledger.rows.length"><td colspan="6">No matching activity.</td></tr></tbody></table></div><div class="flex gap-3"><button class="acc-button" :disabled="busy || page === 1" @click="paginate(-1)">Previous</button><span>Page {{ page }} · {{ ledger.total }} lines</span><button class="acc-button" :disabled="busy || page * 50 >= ledger.total" @click="paginate(1)">Next</button></div></template></section>
            <section v-if="tab === 'audit'" class="acc-card space-y-3"><h2 class="font-semibold">Accounting audit history</h2><button class="acc-button" :disabled="busy" @click="run(async () => { audit = (await axios.get(url('audit'))).data; })">Verify chain</button><p v-if="audit">{{ audit.valid ? 'Valid' : 'INVALID' }} · {{ audit.count }} events · checkpoint {{ audit.head }}</p><details v-for="e in data.events.data" :key="e.id" class="border-b p-2"><summary>#{{ e.id }} · {{ e.created_at }} · Actor {{ e.actor_id }} · {{ e.action }}</summary><pre class="max-h-64 overflow-auto whitespace-pre-wrap text-xs">{{ e.payload }}</pre></details><div class="flex gap-3"><button class="acc-button" :disabled="busy || page === 1" @click="paginate(-1)">Previous</button><span>Page {{ page }}</span><button class="acc-button" :disabled="busy || !data.events.next_page_url" @click="paginate(1)">Next</button></div></section>
            <section v-if="tab === 'tally' && permissions.TALLY && data.tally" class="acc-card space-y-3"><h2 class="font-semibold">TallyPrime exchange</h2><button class="acc-button" :disabled="busy" @click="run(async () => { connection = (await axios.post(url('tally.connection'))).data; })">Check listener</button><p v-if="connection">{{ connection.status }} · Company acceptance remains unverified until a matching voucher receipt.</p><p>Listener {{ data.tally.configured_listener ? 'configured on application host' : 'not configured (GST_TALLY_URL required)' }}. A confirmed receipt requires Tally to report a created voucher ID. Verify the exact company and ledger mappings in a backed-up test company first.</p><form v-if="permissions.ADMIN" class="flex flex-wrap items-center gap-3" @submit.prevent="run(() => axios.post(url('tally.config'), { tally_company: company, tally_enabled: enabled }), 'Configuration saved.')"><label>Exact Tally company<input v-model="company" required maxlength="200" /></label><label><input v-model="enabled" type="checkbox" /> Enable exchange</label><button class="acc-button" :disabled="busy">Save</button></form><a :href="route('gst-compliance.index')" class="text-indigo-700">Open independently reviewed inbound Tally staging</a><p class="text-sm">Uncertain or failed deliveries require inspection of the target GUID. Stop old workers and confirm absence before allowing another send.</p><div v-for="j in data.tally.jobs.data" :key="j.id" class="space-y-2 rounded border p-3"><p>#{{ j.id }} · Journal #{{ j.journal_id }} · {{ j.company }} · <strong>{{ j.status }}</strong> · {{ j.attempts }} attempts</p><p class="break-all text-xs">GUID {{ j.guid }}</p><p v-if="j.last_error" class="text-red-700">{{ j.last_error }}</p><button v-if="j.status === 'pending'" class="acc-button" :disabled="busy" @click="confirm('tally.send',j)">Send frozen voucher</button><button v-if="['failed','uncertain','sending'].includes(j.status)" class="acc-button" @click="confirm('resolve',j)">Record reconciliation decision</button></div><p v-if="!data.tally.jobs.data.length">Queue a posted journal from the Journal register.</p><div class="flex gap-3"><button class="acc-button" :disabled="busy || page === 1" @click="paginate(-1)">Previous</button><span>Page {{ page }}</span><button class="acc-button" :disabled="busy || !data.tally.jobs.next_page_url" @click="paginate(1)">Next</button></div></section>
            <section v-if="permissions.ADMIN" class="acc-card space-y-3"><h2 class="font-semibold">Accounting month control</h2><form class="flex flex-wrap items-end gap-3" @submit.prevent="run(() => axios.post(url('periods'), { period, closed: periodClosed, reason: periodReason }), 'Period control recorded.')"><label>Month<input v-model="period" type="month" required /></label><label>Reason<input v-model="periodReason" required minlength="10" maxlength="2000" /></label><label><input v-model="periodClosed" type="checkbox" /> Closed</label><button class="acc-button" :disabled="busy">Record month status</button></form><p v-for="p in data.periods" :key="p.id">{{ p.period }} · {{ p.closed ? 'Closed' : 'Open' }}</p></section>
        </main>
        <div v-if="account" class="acc-overlay" role="dialog" aria-modal="true" aria-labelledby="account-title"><form class="acc-modal" @submit.prevent="saveAccount"><h2 id="account-title" class="text-xl font-semibold">{{ account.id ? 'Edit' : 'Create / classify' }} account</h2><div class="grid gap-3 md:grid-cols-2"><label>Code<input v-model="account.code" required maxlength="50" /></label><label>Name<input v-model="account.title" required maxlength="255" /></label><label>Portal group<select v-model="account.account_type_id" required><option value="" disabled>Select group</option><option v-for="g in data.groups" :key="g.id" :value="g.id">{{ g.title }}</option></select></label><label>Classification<select v-model="account.type" required><option v-for="t in ['asset','liability','equity','income','expense']" :key="t">{{ t }}</option></select></label><label>Parent<select v-model="account.parent_id"><option value="">None</option><option v-for="a in data.accounts.filter(a => a.classification_id && a.type === account.type && a.classification_id !== account.id)" :key="a.id" :value="a.classification_id">{{ a.title }}</option></select></label><label>Control role<select v-model="account.control"><option value="">None</option><option v-for="t in ['receivable','payable','bank','cash']" :key="t">{{ t }}</option></select></label><label>GST classification<select v-model="account.tax_class"><option value="">None</option><option v-for="t in ['input_cgst','input_sgst','input_igst','input_cess','output_cgst','output_sgst','output_igst','output_cess']" :key="t">{{ t }}</option></select></label><label><input v-model="account.active" type="checkbox" /> Active</label></div><p v-if="!data.groups.length" class="text-amber-800">Initialize the existing plant chart of accounts before creating ledgers.</p><p v-if="failed" role="alert" class="text-red-700">{{ message }}</p><div class="flex gap-3"><button class="acc-button" :disabled="busy">Save account</button><button type="button" class="acc-button" :disabled="busy" @click="account = null">Cancel</button></div></form></div>
        <div v-if="journal" class="acc-overlay" role="dialog" aria-modal="true" aria-labelledby="journal-title"><form class="acc-modal max-w-5xl" @submit.prevent="saveJournal"><h2 id="journal-title" class="text-xl font-semibold">{{ journal.voucher_number || 'New journal / opening balance' }} · {{ journal.display_status || journal.is_status }}</h2><p v-if="journal.reversed_by">Reversed by journal #{{ journal.reversed_by }}. The original is preserved.</p><fieldset :disabled="!editableJournal || busy" class="space-y-3"><div class="grid gap-3 md:grid-cols-3"><label>Date<input v-model="journal.date" type="date" required /></label><label>Reference<input v-model="journal.reference" required maxlength="255" /></label><label>Description<input v-model="journal.narration" required maxlength="4000" /></label></div><div v-for="(l,i) in journal.lines" :key="i" class="grid gap-2 rounded border p-2 md:grid-cols-5"><label>Ledger<select v-model="l.account_id" required><option value="" disabled>Select ledger</option><option v-for="a in data.accounts.filter(a => a.classification_id && a.status)" :key="a.id" :value="a.id">{{ a.code }} · {{ a.title }}</option></select><span v-if="!editableJournal">{{ names[l.account_id] }}</span></label><label>Debit ₹<input v-model="l.debit" inputmode="decimal" required /></label><label>Credit ₹<input v-model="l.credit" inputmode="decimal" required /></label><label>Narration<input v-model="l.narration" maxlength="255" /></label><button v-if="journal.lines.length > 2" type="button" class="acc-button self-end" @click="journal.lines.splice(i,1)">Remove</button></div><button type="button" class="acc-button" @click="journal.lines.push({account_id:'',debit:'0',credit:'0',narration:''})">Add line</button></fieldset><p v-if="failed" role="alert" class="text-red-700">{{ message }}</p><div class="flex gap-3"><button v-if="editableJournal && (journal.id ? permissions.UPDATE : permissions.CREATE)" class="acc-button" :disabled="busy">Save balanced draft</button><button type="button" class="acc-button" :disabled="busy" @click="journal = null">Close</button></div></form></div>
        <div v-if="confirmation" class="acc-overlay" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><form class="acc-modal" @submit.prevent="execute"><h2 id="confirm-title" class="text-xl font-semibold">Confirm {{ confirmation.action }}</h2><p>Plant {{ data.plant_id }} · Record #{{ confirmation.record.id }}. Posted records remain in the books; reversal creates a separate balancing entry.</p><template v-if="confirmation.action === 'reverse'"><label>Reversal date<input v-model="reversalDate" type="date" required /></label><label>Reason<textarea v-model="reason" required minlength="10" maxlength="2000" /></label></template><template v-if="confirmation.action === 'resolve'"><label>Verified outcome<select v-model="confirmation.resolution" required><option value="confirmed">Matching target voucher confirmed</option><option value="retry_absent">Old workers stopped and target GUID verified absent</option></select></label><label>Evidence<textarea v-model="reason" required minlength="20" maxlength="4000" /></label></template><p v-if="failed" role="alert" class="text-red-700">{{ message }}</p><div class="flex gap-3"><button class="acc-button" :disabled="busy">{{ busy ? 'Working…' : 'Confirm' }}</button><button type="button" class="acc-button" :disabled="busy" @click="confirmation = null">Cancel</button></div></form></div>
    </AppLayout>
</template>

